using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public enum HotelGuestTypeKind { Individual = 1, Couple = 2, Family = 3, Group = 4, Corporate = 5, Vip = 6, Government = 7, Crew = 8, LongStay = 9, Other = 10 }

public sealed class HotelGuestTypeProfile
{
    private HotelGuestTypeProfile() { }
    public Guid HotelGuestTypeProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public HotelGuestTypeKind Kind { get; private set; } public string? RequiredFields { get; private set; } public string? DefaultRateCode { get; private set; } public string? DefaultPaymentMethodCode { get; private set; } public string? DefaultMarketCode { get; private set; } public string? DefaultSourceCode { get; private set; } public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelGuestTypeProfile Create(PropertyId propertyId, string code, string name, HotelGuestTypeKind kind, string? requiredFields, string? defaultRateCode, string? defaultPaymentMethodCode, string? defaultMarketCode, string? defaultSourceCode, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, kind, from, to); return new() { HotelGuestTypeProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = code.Trim().ToUpperInvariant(), Name = name.Trim(), Kind = kind, RequiredFields = Normalize(requiredFields), DefaultRateCode = Normalize(defaultRateCode), DefaultPaymentMethodCode = Normalize(defaultPaymentMethodCode), DefaultMarketCode = Normalize(defaultMarketCode), DefaultSourceCode = Normalize(defaultSourceCode), EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, HotelGuestTypeKind kind, string? requiredFields, string? defaultRateCode, string? defaultPaymentMethodCode, string? defaultMarketCode, string? defaultSourceCode, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, kind, from, to); Code = code.Trim().ToUpperInvariant(); Name = name.Trim(); Kind = kind; RequiredFields = Normalize(requiredFields); DefaultRateCode = Normalize(defaultRateCode); DefaultPaymentMethodCode = Normalize(defaultPaymentMethodCode); DefaultMarketCode = Normalize(defaultMarketCode); DefaultSourceCode = Normalize(defaultSourceCode); EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; } private static void Validate(string code, string name, HotelGuestTypeKind kind, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_GUEST_TYPE_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_GUEST_TYPE_NAME_REQUIRED"); if (!Enum.IsDefined(kind)) throw new ArgumentException("HOTEL_GUEST_TYPE_KIND_INVALID"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_GUEST_TYPE_EFFECTIVE_RANGE_INVALID"); } private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}
